package br.com.orientec.backend.adapter.out.persistence.entity.usuario; import jakarta.persistence.*; @Entity @Table(name="permissao") public class Permissao { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String codigo; @Column(nullable=false) private String descricao; @Column(nullable=false) private String modulo; @Column(nullable=false) private boolean ativo=true; public Permissao(){} public Long getId(){return id;} public String getCodigo(){return codigo;} public String getDescricao(){return descricao;} public String getModulo(){return modulo;} public boolean isAtivo(){return ativo;} public void setCodigo(String v){codigo=v;} public void setDescricao(String v){descricao=v;} public void setModulo(String v){modulo=v;} public void setAtivo(boolean v){ativo=v;} }